import csv, json, models

def read(path):
 with open(path, newline='') as f: return list(csv.DictReader(f))
registry={r['unit']:r['cohort'] for r in read('registry.csv')}
assign={r['acquisition']:r['unit'] for r in read('assignments.csv')}
rows=read('observations.csv')
for r in rows:
 r['unit']=assign[r['acquisition']]
 for k in ('x','z','y'): r[k]=float(r[k])
fit=[r for r in rows if registry[r['unit']]=='H']
test=[r for r in rows if registry[r['unit']]=='Q']
assert len(fit)+len(test)==len(rows)==len({r['id'] for r in rows})
a=models.loss('reference',fit,test,category=False)
b=models.loss('candidate',fit,test,category=False)
choice='candidate' if a-b>1e-10 else 'reference'
index={r['id']:r['split'] for r in read('run_index.csv')}
mismatches=[r['id'] for r in rows if index[r['id']] != ('fit' if registry[r['unit']]=='H' else 'test')]
answer={'published_run':'withdraw' if mismatches else 'certify','service_recipe':choice,'reference_loss':round(a,6),'candidate_loss':round(b,6)}
release={'recipe':choice,'fit_ids':[r['id'] for r in fit], 'test_ids':[r['id'] for r in test]}
for path,data in [('answer.json',answer),('release.json',release)]:
 with open(path,'w') as f: json.dump(data,f,indent=2); f.write('\n')
print(answer)
print('fit',len(fit),'test',len(test),'mismatched',len(mismatches),'losses',a,b)
print('files verified', all(json.load(open(p))==d for p,d in [('answer.json',answer),('release.json',release)]))

