import csv, json
from models import loss

def read(name):
 with open(name,newline='') as f: return list(csv.DictReader(f))
obs=read('observations.csv'); assigns=read('assignments.csv'); regs=read('registry.csv')
ass={r['acquisition']:r['unit'] for r in assigns}
reg={r['unit']:r['cohort'] for r in regs}
rows=[]
for o in obs:
 rows.append({'id':o['id'],'unit':ass[o['acquisition']],'x':float(o['visit']),'z':float(o['z']),'y':float(o['y'])})
fit=[r for r in rows if reg[r['unit']]=='H']
test=[r for r in rows if reg[r['unit']]=='Q']
ref=loss('reference',fit,test,category=False)
cand=loss('candidate',fit,test,category=False)
recipe='candidate' if cand < ref-1e-10 else 'reference'
idx={x['id']:x['split'] for x in read('run_index.csv')}
print(json.dumps({'n_obs':len(rows),'fit':len(fit),'test':len(test),'reference_loss':ref,'candidate_loss':cand,'recipe':recipe,'filed_index_count':len(idx),'filed_split_counts':{s:sum(1 for v in idx.values() if v==s) for s in set(idx.values())}},indent=2))
answer={'published_run':'withdraw','service_recipe':recipe,'reference_loss':round(ref,6),'candidate_loss':round(cand,6)}
release={'recipe':recipe,'fit_ids':[r['id'] for r in fit],'test_ids':[r['id'] for r in test]}
for name,data in [('answer.json',answer),('release.json',release)]:
 with open(name,'w') as f: json.dump(data,f,indent=2); f.write('\n')
print('WROTE',json.dumps(answer), 'release counts',len(release['fit_ids']),len(release['test_ids']))

