import csv, json, models
from collections import Counter

def read(f):
 with open(f, newline='') as h: return list(csv.DictReader(h))
obs=read('observations.csv'); assignments=read('assignments.csv'); registry=read('registry.csv'); run=read('run_index.csv')
a={r['acquisition']:r['unit'] for r in assignments}; locks={r['unit']:float(r['lock_visit']) for r in registry}
assert len(a)==len(assignments) and len(locks)==len(registry)
assert len({r['id'] for r in obs})==len(obs)
rows=[{'id':r['id'],'unit':a[r['acquisition']],'x':float(r['x']),'z':float(r['z']),'y':float(r['y']),'visit':float(r['visit'])} for r in obs]
fit=[r for r in rows if r['visit']<=locks[r['unit']]]; test=[r for r in rows if r['visit']>locks[r['unit']]]
ref=models.loss('reference',fit,test,category=False); cand=models.loss('candidate',fit,test,category=False)
recipe='candidate' if ref-cand>1e-10 else 'reference'
runmap={r['id']:r['split'] for r in run}
assert len(runmap)==len(run) and set(runmap)=={r['id'] for r in rows}
mismatches=[r['id'] for r in rows if runmap[r['id']] != ('fit' if r['visit']<=locks[r['unit']] else 'test')]
answer={'published_run':'withdraw' if mismatches else 'certify','service_recipe':recipe,'reference_loss':round(ref,6),'candidate_loss':round(cand,6)}
release={'recipe':recipe,'fit_ids':[r['id'] for r in fit],'test_ids':[r['id'] for r in test]}
with open('answer.json','w') as f: json.dump(answer,f,indent=2); f.write('\n')
with open('release.json','w') as f: json.dump(release,f,indent=2); f.write('\n')
print(answer); print('fit',len(fit),'test',len(test),'mismatches',len(mismatches)); print('mismatches',mismatches); print('registered units',len(locks),'observed units',len(set(r['unit'] for r in rows)))

