import csv, collections, json, models
read=lambda f:list(csv.DictReader(open(f,newline='')))
reg=read('registry.csv'); ass=read('assignments.csv'); obs=read('observations.csv'); idx=read('run_index.csv')
for name,rows,key in [('registry',reg,'unit'),('assignments',ass,'acquisition'),('observations',obs,'id'),('run_index',idx,'id')]:
 c=collections.Counter(r[key] for r in rows); print(name,len(rows),'unique',len(c),'duplicates',sum(v-1 for v in c.values()))
units={r['unit']:float(r['lock_visit']) for r in reg}; mapping={r['acquisition']:r['unit'] for r in ass}
print('missing acquisitions',set(r['acquisition'] for r in obs)-mapping.keys(), 'missing units',set(mapping.values())-units.keys())
fit=[]; test=[]
for o in obs:
 u=mapping[o['acquisition']]; row={'id':o['id'],'unit':u,**{k:float(o[k]) for k in ('x','z','y')}}
 (fit if float(o['visit'])<=units[u] else test).append(row)
ref=models.loss('reference',fit,test,category=False); cand=models.loss('candidate',fit,test,category=False)
index={r['id']:r['split'] for r in idx}; expected={**{r['id']:'fit' for r in fit},**{r['id']:'test' for r in test}}
print('fit/test',len(fit),len(test),'losses',ref,cand,'split differences',sum(index.get(k)!=v for k,v in expected.items()),'index extras',len(index.keys()-expected.keys()))
print('unit overlap',len(set(r['unit'] for r in fit)&set(r['unit'] for r in test)))
recipe='candidate' if cand < ref-1e-10 else 'reference'
answer={'published_run':'certify' if index==expected else 'withdraw','service_recipe':recipe,'reference_loss':round(ref,6),'candidate_loss':round(cand,6)}
release={'recipe':recipe,'fit_ids':[r['id'] for r in fit],'test_ids':[r['id'] for r in test]}
for filename,data in [('answer.json',answer),('release.json',release)]:
 with open(filename,'w') as f: json.dump(data,f,indent=2); f.write('\n')
print('answer',answer)

