def read(f):
 with open(f,newline='') as h:return list(csv.DictReader(h))
o=read('observations.csv'); a=read('assignments.csv'); g=read('registry.csv'); ix=read('run_index.csv')
for data,k in [(o,'id'),(a,'acquisition'),(g,'unit'),(ix,'id')]:
 c=collections.Counter(r[k] for r in data); print(k,len(data),'duplicates',[(x,n) for x,n in c.items() if n>1])
am={r['acquisition']:r['unit'] for r in a}; locks={r['unit']:float(r['lock_visit']) for r in g}; idx={r['id']:r['split'] for r in ix}
rows=[dict(id=r['id'],unit=am[r['acquisition']],x=float(r['x']),z=float(r['z']),y=float(r['y']),visit=float(r['visit'])) for r in o]
fit=[r for r in rows if r['visit']<=locks[r['unit']]]; test=[r for r in rows if r['visit']>locks[r['unit']]]
