print('losses',ref,can)
answer=json.load(open('answer.json')); release=json.load(open('release.json'))
assert answer=={'published_run':'withdraw','service_recipe':'candidate','reference_loss':round(ref,6),'candidate_loss':round(can,6)}
assert release['recipe']=='candidate' and len(release['fit_ids'])==len(fit) and set(release['fit_ids'])=={r['id'] for r in fit} and len(release['test_ids'])==len(test) and set(release['test_ids'])=={r['id'] for r in test}
