import csv, json, collections, models
read=lambda f:list(csv.DictReader(open(f)))
a={r['acquisition']:r['unit'] for r in read('assignments.csv')}
c={r['unit']:r['cohort'] for r in read('registry.csv')}
rows=read('observations.csv')
for r in rows:
 r['unit']=a[r['acquisition']]
 for k in ('x','z','y'): r[k]=float(r[k])
fit=[r for r in rows if c[r['unit']]=='H']; test=[r for r in rows if c[r['unit']]=='Q']
idx={r['id']:r['split'] for r in read('run_index.csv')}
print('counts',len(fit),len(test),collections.Counter((c[r['unit']],idx[r['id']]) for r in rows))
ref=models.loss('reference',fit,test,category=False); cand=models.loss('candidate',fit,test,category=False)
print('loss',ref,cand,'difference',ref-cand)
print('filed losses',*[models.loss(recipe,[r for r in rows if idx[r['id']]=='fit'],[r for r in rows if idx[r['id']]=='test'],category=False) for recipe in ('reference','candidate')])
recipe='candidate' if ref-cand>1e-10 else 'reference'
answer={'published_run':'withdraw','service_recipe':recipe,'reference_loss':round(ref,6),'candidate_loss':round(cand,6)}
release={'recipe':recipe,'fit_ids':[r['id'] for r in fit],'test_ids':[r['id'] for r in test]}
with open('answer.json','w') as f: json.dump(answer,f,indent=2); f.write('\n')
with open('release.json','w') as f: json.dump(release,f,indent=2); f.write('\n')
print('answer',answer)
print('release count verified',len(release['fit_ids']),len(release['test_ids']),len(set(release['fit_ids']) & set(release['test_ids'])))

